(* [comment removed for export] *)
Ltac wseed H l h :=
  let go A2 s2 := (let W := fresh "WS" in assert (W : hideL (A2 + s2 <= l \/ h <= A2)); [unfold hideL|]) in
  lazymatch type of H with
  | rw_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  | ro_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  end.

(* [comment removed for export] *)
Ltac kill_lit K := exfalso; clear - K; rewrite ?unsigned_lit in K by (clear; cbn; lia); cbn in K; lia.

Definition ALOC_RS_EOS : Z := 0x1177a0.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition rs_eof_E (c : pcore) : ecv := if pc_state c =? 0 then EC_http_loc HE_END_OF_STREAM ALOC_RS_EOS else fst (peof_res c).
Definition rs_eof_c (c : pcore) : pcore := if pc_state c =? 0 then c else snd (peof_res c).
Definition rs_eof_g (c : pcore) (g : bool) : bool := if pc_state c =? 0 then true else peof_assigns c || g.

Lemma peof_res_cases : forall c, pcore_ok c -> pc_state c <> 0 ->
  (exists loc, peof_res c = (EC_http_loc HE_PARTIAL_MESSAGE loc, c) /\ (loc = ALOC_PEOF_1 \/ loc = ALOC_PEOF_2))
  \/ (peof_res c = (EC_clear, snd (peof_res c)) /\ pc_state (snd (peof_res c)) = 11).
Proof.
  intros c OK NZ. unfold peof_res.
  destruct (pc_state c <=? 2) eqn:L2; [left; exists ALOC_PEOF_1; split; [reflexivity | left; reflexivity]|].
  destruct (peof_body_flags c).
  - destruct (pc_state c =? 11) eqn:E11.
    + right. split; [reflexivity|]. cbn. apply Z.eqb_eq in E11. exact E11.
    + left. exists ALOC_PEOF_2. split; [reflexivity | right; reflexivity].
  - right. split; [reflexivity|]. cbn. reflexivity.
Qed.
