(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rs_eof_W (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -104); (P, P + 80); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z.

Definition rs_eof_post (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (lo shi E P tot : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
       munch (rs_eof_W lo sp P E) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' P (ParserCoreCells (rs_eof_c c) pad7 pad2)
    /\ rw_cells asegs m' E (ErrCodeCells (rs_eof_E c))
    /\ AHttpCat m' (rs_eof_g c g) /\ AXStatics2 m' /\ ACONST m' /\ stack0 m' lo shi
    /\ rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo tot m' ms'.

